-- ============================================
-- LUMA — Thème 8 : LONG 3/3 x4 — Un affrontement final avec plusieurs issues
-- ============================================


update scenarios set content = '{"characters": {"villain": "l''antagoniste", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "villain", "text": "So, you''ve finally come, hero. Did you truly believe you could stop me?", "text_fr": "Alors, vous êtes enfin venu, héros. Pensiez-vous vraiment pouvoir m''arrêter ?", "choices": [{"text": "I don''t need to believe. I simply need to try.", "text_fr": "Je n''ai pas besoin de croire. J''ai juste besoin d''essayer.", "next": "n2"}, {"text": "Whatever pain drove you here, it doesn''t have to end in destruction.", "text_fr": "Quelle que soit la douleur qui vous a mené ici, ça n''a pas besoin de finir dans la destruction.", "next": "n2b"}, {"text": "(Say nothing, and draw your weapon, ready for battle.)", "text_fr": "(Ne dis rien, et dégaine ton arme, prêt au combat.)", "next": "n2c"}]}, "n2": {"speaker": "villain", "text": "Bold words. Let''s see if your actions match them.", "text_fr": "Des mots audacieux. Voyons si vos actions sont à la hauteur.", "choices": [{"text": "(Prepare to fight, but keep watching for an opening to reason with him.)", "text_fr": "(Prépare-toi à combattre, mais reste attentif à une ouverture pour raisonner avec lui.)", "next": "n3"}, {"text": "Before we fight — tell me what truly happened to you.", "text_fr": "Avant qu''on se batte — dites-moi ce qui vous est vraiment arrivé.", "next": "n3b"}]}, "n2b": {"speaker": "villain", "text": "(Pauses, a flicker of doubt crossing his face) You know nothing of my pain.", "text_fr": "(Fait une pause, un éclair de doute traversant son visage) Vous ne savez rien de ma douleur.", "choices": [{"text": "Then tell me. Let me understand before this ends in bloodshed.", "text_fr": "Alors dites-moi. Laissez-moi comprendre avant que ça finisse dans le sang.", "next": "n3b"}, {"text": "Perhaps not. But pain that consumes everything helps no one, least of all you.", "text_fr": "Peut-être pas. Mais la douleur qui consume tout n''aide personne, surtout pas vous.", "next": "n3c"}]}, "n2c": {"speaker": "villain", "text": "(Smirks) A fighter, then. Very well, let''s dance.", "text_fr": "(Sourit narquoisement) Un combattant, alors. Très bien, dansons.", "choices": [{"text": "(Engage in combat, striking with precision and focus.)", "text_fr": "(Engage le combat, frappant avec précision et concentration.)", "next": "n3d"}]}, "n3": {"speaker": "villain", "text": "(Circles you, weapon raised) You fight well. But strength alone won''t save this kingdom.", "text_fr": "(Tourne autour de vous, arme levée) Vous vous battez bien. Mais la force seule ne sauvera pas ce royaume.", "choices": [{"text": "Then let''s end this — not with more violence, but with truth.", "text_fr": "Alors terminons ça — pas avec plus de violence, mais avec la vérité.", "next": "n4"}]}, "n3b": {"speaker": "villain", "text": "(Weapon lowers slightly) They took everything from me. My family, my home, my honor.", "text_fr": "(Baisse légèrement son arme) Ils m''ont tout pris. Ma famille, ma maison, mon honneur.", "choices": [{"text": "That''s a wound no one should carry alone. Let me help you find another way.", "text_fr": "C''est une blessure que personne ne devrait porter seul. Laissez-moi vous aider à trouver une autre voie.", "next": "n4"}]}, "n3c": {"speaker": "villain", "text": "(Grip tightens on his weapon) You think you understand suffering? You know nothing!", "text_fr": "(Serre sa prise sur son arme) Vous pensez comprendre la souffrance ? Vous ne savez rien !", "choices": [{"text": "Maybe not yours specifically. But I know destruction never truly heals pain.", "text_fr": "Peut-être pas la vôtre spécifiquement. Mais je sais que la destruction ne guérit jamais vraiment la douleur.", "next": "n4"}]}, "n3d": {"speaker": "villain", "text": "(Blocks your strike, impressed) Skilled. But skill alone won''t be enough today.", "text_fr": "(Bloque votre coup, impressionné) Habile. Mais l''habileté seule ne suffira pas aujourd''hui.", "choices": [{"text": "(Pause mid-fight) Wait — this doesn''t have to end in death. There''s still a choice.", "text_fr": "(Fait une pause en plein combat) Attends — ça n''a pas besoin de finir dans la mort. Il y a encore un choix.", "next": "n4"}, {"text": "(Continue fighting with everything you have.)", "text_fr": "(Continue à combattre de toutes tes forces.)", "next": "n4b"}]}, "n4": {"speaker": "villain", "text": "(Weapon trembles slightly) ...A choice? After everything, you still believe in that?", "text_fr": "(Arme tremble légèrement) ...Un choix ? Après tout ça, vous croyez encore à ça ?", "choices": [{"text": "I do. Everyone deserves one more chance to choose differently.", "text_fr": "Oui. Tout le monde mérite une chance de plus pour choisir différemment.", "next": "n5"}, {"text": "I have to. It''s the only thing that separates us from becoming what we fight.", "text_fr": "Je dois y croire. C''est la seule chose qui nous distingue de ce que nous combattons.", "next": "n5"}]}, "n4b": {"speaker": "narrator", "text": "(The battle rages fiercely, both fighters pushed to their absolute limits.)", "text_fr": "(La bataille fait rage férocement, les deux combattants poussés à leurs limites absolues.)", "choices": [{"text": "(Land a final decisive strike, ending the fight through combat.)", "text_fr": "(Porte un coup final décisif, terminant le combat par la force.)", "next": "end_combat"}]}, "n5": {"speaker": "villain", "text": "(Weapon falls from his hand, clattering to the ground) I... I don''t know how to stop anymore.", "text_fr": "(Son arme tombe de sa main, tombant au sol dans un bruit métallique) Je... je ne sais plus comment m''arrêter.", "choices": [{"text": "Then let this be the moment you finally do. Walk away from this path with me.", "text_fr": "Alors que ce soit le moment où vous vous arrêtez enfin. Éloignez-vous de cette voie avec moi.", "next": "n6"}]}, "n6": {"speaker": "villain", "text": "(Falls to his knees, exhausted) I... yes. I''m so tired of carrying this hatred.", "text_fr": "(Tombe à genoux, épuisé) Je... oui. Je suis si fatigué de porter cette haine.", "choices": [{"text": "Then let it go. The kingdom, and you, deserve a chance to heal.", "text_fr": "Alors laissez-la partir. Le royaume, et vous, méritez une chance de guérir.", "next": "end_redeemed"}]}, "end_redeemed": {"speaker": "narrator", "text": "(The kingdom rebuilds not through vengeance, but through the mercy shown in its darkest hour.)", "text_fr": "(Le royaume se reconstruit non par la vengeance, mais par la pitié montrée à son heure la plus sombre.)", "end": true, "ending_label": "Le mal vaincu par la compassion, non la violence 🕊️⚔️"}, "end_combat": {"speaker": "narrator", "text": "(The villain falls, defeated. The kingdom is saved, but the cost of battle lingers heavily.)", "text_fr": "(Le méchant tombe, vaincu. Le royaume est sauvé, mais le coût de la bataille pèse lourdement.)", "end": true, "ending_label": "Victoire par le combat, mais à quel prix ⚔️💭"}}}'::jsonb, is_playable = true
where title = 'Un affrontement final avec plusieurs issues'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
